	(110, 'Madhya Pradesh State Service Exam Assistant District Prosecution Officer Recruitment 2026 Admit Card for 107 Post', 'mppsc-adpo-2026-admit-card', 'admit_card', 'Madhya Pradesh Public Service Commission (MPPSC)', 'Madhya Pradesh', 'Graduate', 107, NULL, '2026-10-21', 'Madhya Pradesh Public Service Commission (MPPSC) has released the admit card for the Assistant District Prosecution Officer (ADPO) Exam 2026. Candidates enrolled for this exam can download the admit card. Read the notification for eligibility, post details, selection procedure, age limit, pay scale and all other information.', '## Before the exam\r\n- Carry a printed copy of the admit card to the exam centre\r\n- Carry an original photo ID proof\r\n- Reach the centre well before the reporting time', '{"dates": [{"label": "Application Begin", "value": "10/07/2026 (Re-Open)"}, {"label": "Last Date for Apply Online", "value": "24/07/2026"}, {"label": "Last Date Pay Exam Fee", "value": "24/07/2026"}, {"label": "Form Correction Last Date", "value": "10 - 26 July 2026"}, {"label": "With Late Fee Phase I Last Date", "value": "25/07/2026 to 31/07/2026"}, {"label": "With Late Fee Phase II Last Date", "value": "01/08/2026 to 23/09/2026"}, {"label": "Exam Date", "value": "04/11/2026", "hl": true}, {"label": "Admit Card Available", "value": "21/10/2026", "hl": true}], "fees": [{"label": "General / Other State", "value": "540/-"}, {"label": "OBC / EWS / SC / ST", "value": "Rs. 290/-"}, {"label": "Late fee Phase I", "value": "3000/- + Portal Fee"}, {"label": "Late fee Phase II", "value": "25000/- + Portal Fee"}], "fee_notes": ["Portal charges included: Rs. 40/-", "Correction charge: Rs. 50/-", "Pay the examination fee through E-Challan, Debit Card, Credit Card, Net Banking or an authorized kiosk."], "age": [{"label": "Minimum Age", "value": "21 Years"}, {"label": "Maximum Age", "value": "40 Years"}], "age_note": "Age as on 01/01/2027. Extra relaxation as per MPPSC ADPO Recruitment Rules 2026.", "vacancy": [{"post": "Assistant District Prosecution Officer (ADPO)", "total": "107", "eligibility": "Bachelor\'s Degree in Law (LLB) from any recognized university in India. Read the notification for more eligibility details."}], "how_to": ["Candidates can apply between 10/07/2026 and 24/07/2026.", "Read the notification fully before you fill in the application form.", "Keep your documents ready: eligibility proof, ID proof, address and basic details.", "Keep scanned copies ready: photo, signature and ID proof.", "Check the preview and every column carefully before you submit.", "Pay the application fee, if required. The form is not complete without the fee.", "Take a printout of the final submitted form."], "links": [{"label": "Download Admit Card", "url": "https://mppsc.mp.gov.in", "hl": true}, {"label": "Download Exam Notice", "url": "https://mppsc.mp.gov.in"}, {"label": "Apply Online", "url": "https://mppsc.mp.gov.in"}, {"label": "Candidate Login", "url": "https://mppsc.mp.gov.in"}, {"label": "Download Re-Open Notice", "url": "https://mppsc.mp.gov.in"}, {"label": "Download Notification", "url": "https://mppsc.mp.gov.in"}, {"label": "Official Website", "url": "https://mppsc.mp.gov.in"}]}', NULL, 'https://mppsc.mp.gov.in', NULL, 'published', 1252, '2026-10-21 13:50:00', '2026-11-11 04:57:16'),
	(111, 'Demo Commission Recruitment 2026 - Sample Post', 'demo-commission-recruitment-2026-sample-post', 'job', 'Demo Public Service Commission', 'All India', 'Graduate', 120, '2026-12-01', '2026-11-11', 'This is a sample post that shows every section. Replace it with a real notification.', NULL, '{"dates":[{"label":"Notification date","value":"01 July 2026","hl":false},{"label":"Application start","value":"05 July 2026","hl":false},{"label":"Last date to apply online","value":"31 July 2026","hl":true},{"label":"Last date to pay fee","value":"31 July 2026","hl":false},{"label":"Exam date","value":"To be announced","hl":false}],"fees":[{"label":"General / OBC / EWS","value":"Rs. 100","hl":false},{"label":"SC / ST","value":"Rs. 25","hl":false},{"label":"Female / PH","value":"Rs. 0","hl":false}],"fee_notes":["Pay the fee by debit card, credit card or net banking.","The fee is not refundable."],"age":[{"label":"Minimum age","value":"21 years","hl":false},{"label":"Maximum age","value":"40 years","hl":false},{"label":"Age as on","value":"01 July 2026","hl":false}],"age_note":"Age relaxation is given as per the rules of the commission.","vacancy":[{"post":"Section Officer","total":"70","eligibility":"Bachelor degree in any stream from a recognised university."},{"post":"Assistant Officer","total":"50","eligibility":"Bachelor degree with 55% marks."}],"how_to":["Read the official notification fully.","Register on the official website with a valid mobile number and email.","Fill the form and upload photo and signature.","Pay the fee and submit.","Print the final form for your records."],"links":[{"label":"Apply online","url":"https://example.com/apply","hl":true},{"label":"Download notification","url":"https://example.com/notification.pdf","hl":false},{"label":"Official website","url":"https://example.com","hl":false}]}', 'https://example.com/apply', 'https://example.com', NULL, 'published', 3, '2026-11-11 05:50:26', '2026-11-11 06:19:40');
